        return (
            when.minute in self.minutes
            and when.hour in self.hours
            and when.day in self.days_of_month
            and when.month in self.months
        )


def _field(text: str, low: int, high: int) -> frozenset[int]:
    if text == "*":
        return frozenset(range(low, high + 1))
    return frozenset({int(text)})


def parse(expression: str) -> Schedule:
    minute, hour, dom, month, _dow = expression.split()
    return Schedule(
        minutes=_field(minute, 0, 59),
        hours=_field(hour, 0, 23),
        days_of_month=_field(dom, 1, 31),
        months=_field(month, 1, 12),
    )
