def _resolve(wall: datetime, tz) -> datetime:
    """The instant a local wall-clock time happens at, in zone `tz`."""
    when = wall.replace(tzinfo=tz)
    if when.astimezone(timezone.utc).astimezone(tz).replace(tzinfo=None) == wall:
