def _gap_end(when: datetime, tz) -> datetime:
    """The instant the clock jumps to, for a wall time that never happens."""
    after_offset = when.replace(fold=1).utcoffset()
    instant = when.replace(fold=1).astimezone(timezone.utc)  # before the jump
