def describe(expression: str) -> str:
    """One plain-English line for a cron expression."""
    schedule = parse(expression)
    return f"{_time_phrase(schedule)} {_day_phrase(schedule)}".strip()


def _time_phrase(schedule: Schedule) -> str:
    if len(schedule.hours) == 24:
        if len(schedule.minutes) == 60:
            return "every minute"
        step = _step_of(sorted(schedule.minutes), 60)
        if step:
            return f"every {step} minutes"
    hour = next(iter(schedule.hours))
    minute = next(iter(schedule.minutes))
    return f"at {hour:02d}:{minute:02d}"


def _day_phrase(schedule: Schedule) -> str:
    if not schedule.day_of_week_restricted and not schedule.day_of_month_restricted:
        return "every day" if len(schedule.hours) < 24 else ""
    return "on " + ", ".join(WEEKDAY_LABELS[day] for day in sorted(schedule.days_of_week))


def _step_of(values: list[int], wrap: int) -> int | None:
    """The N of a `*/N` field, if the values are exactly every Nth from 0."""
    if len(values) < 2 or values[0] != 0:
        return None
    step = values[1]
    return step if values == list(range(0, wrap, step)) else None''')
